@@ -2,6 +2,8 @@ package org.jsoup.select;

 import org.jsoup.nodes.Element;
 import org.jsoup.nodes.Node;
+import org.jsoup.nodes.PseudoTextElement;
+import org.jsoup.nodes.TextNode;

 import static org.jsoup.select.NodeFilter.FilterResult.CONTINUE;
 import static org.jsoup.select.NodeFilter.FilterResult.STOP;
@@ -24,10 +26,29 @@ public class Collector {
      */
     public static Elements collect (Evaluator eval, Element root) {
         Elements elements = new Elements();
-        NodeTraversor.traverse(new Accumulator(root, elements, eval), root);
+        if (hasMatchText(eval)) {
+            NodeTraversor.traverse(new MatchTextAccumulator(root, elements, eval), root);
+        } else {
+            NodeTraversor.traverse(new Accumulator(root, elements, eval), root);
+        }
         return elements;
     }

+    private static boolean hasMatchText(Evaluator eval) {
+        if (eval instanceof Evaluator.MatchText) {
+            return true;
+        }
+        if (eval instanceof CombiningEvaluator) {
+            CombiningEvaluator comb = (CombiningEvaluator) eval;
+            for (Evaluator e : comb.evaluators) {
+                if (hasMatchText(e)) {
+                    return true;
+                }
+            }
+        }
+        return false;
+    }
+
     private static class Accumulator implements NodeVisitor {
         private final Element root;
         private final Elements elements;
@@ -52,6 +73,145 @@ public class Collector {
         }
     }

+    private static class MatchTextAccumulator implements NodeVisitor {
+        private final Element root;
+        private final Elements elements;
+        private final Evaluator eval;
+        private final Evaluator elementEval;
+        private final Evaluator pseudoEval;
+
+        MatchTextAccumulator(Element root, Elements elements, Evaluator eval) {
+            this.root = root;
+            this.elements = elements;
+            this.eval = eval;
+            // Split the evaluator into element matcher and pseudo element matcher
+            EvalSplit split = splitEval(eval);
+            this.elementEval = split.elementEval;
+            this.pseudoEval = split.pseudoEval;
+        }
+
+        public void head(Node node, int depth) {
+            if (node instanceof Element) {
+                Element el = (Element) node;
+                if (elementEval.matches(root, el)) {
+                    // Element matches, now replace text nodes with pseudo elements
+                    java.util.List<Node> childNodes = new java.util.ArrayList<>(el.childNodes());
+                    for (Node child : childNodes) {
+                        if (child instanceof TextNode) {
+                            TextNode tn = (TextNode) child;
+                            String text = tn.getWholeText();
+                            if (text.trim().length() > 0) {
+                                // Create a pseudo element from the text node
+                                PseudoTextElement pseudo = createPseudoElement(text);
+                                tn.replaceWith(pseudo);
+                                // Check if pseudo element matches additional selectors
+                                if (pseudoEval.matches(root, pseudo)) {
+                                    elements.add(pseudo);
+                                }
+                            }
+                        }
+                    }
+                }
+            }
+        }
+
+        public void tail(Node node, int depth) {
+            // void
+        }
+
+        private PseudoTextElement createPseudoElement(String text) {
+            return new PseudoTextElement(text);
+        }
+    }
+
+    private static class EvalSplit {
+        final Evaluator elementEval;
+        final Evaluator pseudoEval;
+
+        EvalSplit(Evaluator elementEval, Evaluator pseudoEval) {
+            this.elementEval = elementEval;
+            this.pseudoEval = pseudoEval;
+        }
+    }
+
+    private static EvalSplit splitEval(Evaluator eval) {
+        // We need to split the evaluator into:
+        // - elementEval: matches elements (tag, classes, attributes, etc.) but NOT :matchText or pseudo-element selectors
+        // - pseudoEval: matches pseudo elements (:first-child, :last-child, etc.) but NOT :matchText
+
+        if (eval instanceof Evaluator.MatchText) {
+            return new EvalSplit(new Evaluator.AllElements(), new Evaluator.AllElements());
+        }
+
+        if (eval instanceof CombiningEvaluator.And) {
+            CombiningEvaluator.And and = (CombiningEvaluator.And) eval;
+            java.util.List<Evaluator> elementEvals = new java.util.ArrayList<>();
+            java.util.List<Evaluator> pseudoEvals = new java.util.ArrayList<>();
+
+            for (Evaluator e : and.evaluators) {
+                if (e instanceof Evaluator.MatchText) {
+                    continue;
+                } else if (isPseudoElement(e)) {
+                    pseudoEvals.add(e);
+                } else {
+                    elementEvals.add(e);
+                }
+            }
+
+            Evaluator elemEval = elementEvals.isEmpty() ? new Evaluator.AllElements() :
+                                 elementEvals.size() == 1 ? elementEvals.get(0) :
+                                 new CombiningEvaluator.And(elementEvals);
+
+            Evaluator pseudEval = pseudoEvals.isEmpty() ? new Evaluator.AllElements() :
+                                  pseudoEvals.size() == 1 ? pseudoEvals.get(0) :
+                                  new CombiningEvaluator.And(pseudoEvals);
+
+            return new EvalSplit(elemEval, pseudEval);
+        }
+
+        if (isPseudoElement(eval)) {
+            return new EvalSplit(new Evaluator.AllElements(), eval);
+        }
+
+        return new EvalSplit(eval, new Evaluator.AllElements());
+    }
+
+    private static boolean isPseudoElement(Evaluator eval) {
+        return eval instanceof Evaluator.IsFirstChild ||
+               eval instanceof Evaluator.IsLastChild ||
+               eval instanceof Evaluator.IsFirstOfType ||
+               eval instanceof Evaluator.IsLastOfType ||
+               eval instanceof Evaluator.IsOnlyChild ||
+               eval instanceof Evaluator.IsOnlyOfType ||
+               eval instanceof Evaluator.IsNthChild ||
+               eval instanceof Evaluator.IsNthLastChild ||
+               eval instanceof Evaluator.IsNthOfType ||
+               eval instanceof Evaluator.IsNthLastOfType;
+    }
+
+    private static Evaluator removeMatchText(Evaluator eval) {
+        if (eval instanceof Evaluator.MatchText) {
+            return new Evaluator.AllElements();
+        }
+        if (eval instanceof CombiningEvaluator.And) {
+            CombiningEvaluator.And and = (CombiningEvaluator.And) eval;
+            java.util.List<Evaluator> newEvals = new java.util.ArrayList<>();
+            for (Evaluator e : and.evaluators) {
+                if (!(e instanceof Evaluator.MatchText)) {
+                    newEvals.add(e);
+                }
+            }
+            if (newEvals.isEmpty()) {
+                return new Evaluator.AllElements();
+            } else if (newEvals.size() == 1) {
+                return newEvals.get(0);
+            } else {
+                return new CombiningEvaluator.And(newEvals);
+            }
+        }
+        return eval;
+    }
+
     public static Element findFirst(Evaluator eval, Element root) {
         FirstFinder finder = new FirstFinder(root, eval);
         NodeTraversor.filter(finder, root);
